        // pins whole into the iterator slot (never decomposed).
        let src = "def _gen(n):\n    i = 0\n\
                   \x20   while i < n:\n        yield i\n        i = i + 1\n\
                   def total(it):\n    t = 0\n\
                   \x20   for x in it:\n        t = t + x\n\
                   \x20   return t\n\
                   print(total(_gen(5000)))\n";
