    #[cfg(feature = "jit")]
    #[test]
    fn jit_to_bool_int_and_float_branches() {
        // CPython 3.13's `TO_BOOL` on non-bool scalars (`if i & 1:`,
        // `if f:`): lowered as a double negation on the existing
        // `Not` ops.
        let src = "def count(n):\n    t = 0\n    i = 0\n    f = 0.0\n\
                   \x20   while i < n:\n\
                   \x20       if i & 1:\n            t = t + 1\n\
                   \x20       if f:\n            t = t + 10\n\
                   \x20       f = 1.5\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 60:\n    r = count(200)\n    k = k + 1\n\
                   print(r)\n";
        let (out, compiled, deopts) = run_jit(src);
        assert!(compiled >= 1, "TO_BOOL kernel never compiled");
        assert_eq!(deopts, 0, "TO_BOOL lanes should not deopt");
        // odds: 100; `f` truthy from i=1 on: 199 * 10 = 1990.
        assert_eq!(out, "2090\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_generator_while_trailing_yield_parks_natively() {
        // RFC 0073 WS4 — the `while`-shaped yield-dense counter now
        // compiles and parks per yield (see the `for`-shaped sibling
        // above); the park keeps the whole resume cycle native.
        let src = "def counter(n):\n    i = 0\n\
                   \x20   while i < n:\n        yield i\n        i = i + 1\n\
                   t = 0\nk = 0\n\
                   while k < 60:\n\
                   \x20   for v in counter(20):\n        t = t + v\n\
                   \x20   k = k + 1\n\
                   print(t)\n";
        let (out, compiled, resumes, yields) = run_jit_resume(src);
        assert!(compiled >= 1, "yield-dense body never compiled");
        assert!(resumes >= 1, "yield-dense body never resumed natively");
        assert!(yields >= 1, "no native yield exit was taken");
        assert_eq!(out, "11400\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_generator_int_send_falls_back_exactly() {
        // RFC 0071 WS5 — the resume entry admits only `None` and
        // instances on the sent-value lane; an `int` send must take
        // the interpreted resume with identical semantics (including
        // the StopIteration return value).
        let src = "def echo(n):\n    got = 0\n    i = 0\n\
                   \x20   while i < n:\n\
                   \x20       x = yield i\n\
                   \x20       if x is not None:\n            got = got + x\n\
                   \x20       i = i + 1\n\
                   \x20   return got\n\
                   t = 0\nk = 0\n\
                   while k < 60:\n\
                   \x20   g = echo(10)\n    v = next(g)\n\
                   \x20   try:\n\
                   \x20       while True:\n            v = g.send(v * 2)\n\
                   \x20   except StopIteration as e:\n        t = t + e.value\n\
                   \x20   k = k + 1\n\
                   print(t)\n";
        let (out, _compiled, _resumes, _yields) = run_jit_resume(src);
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_str_eq_kernel_compiles_clean() {
        // RFC 0071 WS6 — `==`/`!=` on two str parameters: the seeded
        // retry types the `Str` lanes from the live arguments and the
        // comparison runs through `wpjit_str_eq` (content compare, not
        // identity — the operands are built at runtime).
        let src = "def count(a, b, n):\n    t = 0\n    i = 0\n\
                   \x20   while i < n:\n\
                   \x20       if a == b:\n            t = t + 1\n\
                   \x20       if a != b:\n            t = t + 2\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   s1 = 'he' + 'llo'\n\
                   s2 = 'hel' + 'lo'\n\
                   r = 0\nk = 0\n\
                   while k < 20:\n    r = count(s1, s2, 100)\n    k = k + 1\n\
                   print(r, count(s1, 'other', 100))\n";
        let (out, compiled, deopts) = run_jit(src);
        assert!(compiled >= 1, "str-eq kernel never compiled");
        assert_eq!(deopts, 0, "clean str compare should not deopt");
        assert_eq!(out, "100 200\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_str_len_counts_characters() {
        // RFC 0071 WS6 — `len(s)` through `wpjit_str_len` counts
        // scalar values, not UTF-8 bytes.
        let src = "def total(s, n):\n    t = 0\n    i = 0\n\
                   \x20   while i < n:\n        t = t + len(s)\n        i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 20:\n    r = total('h\u{e9}llo w\u{f6}rld', 100)\n    k = k + 1\n\
                   print(r)\n";
        let (out, compiled, deopts) = run_jit(src);
        assert!(compiled >= 1, "str-len kernel never compiled");
        assert_eq!(deopts, 0, "clean len(str) should not deopt");
        assert_eq!(out, "1100\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_bytes_subscript_and_len() {
        // RFC 0071 WS6 — `data[i % len(data)]` reads bytes as ints
        // through `wpjit_bytes_get` (negative index normalized); the
        // out-of-range read deopts and the interpreter raises the
        // exact IndexError.
        let src = "def total(data, n):\n    t = 0\n    klen = len(data)\n    i = 0\n\
                   \x20   while i < n:\n        t = t + data[i % klen]\n        i = i + 1\n\
                   \x20   return t + data[-1]\n\
                   key = bytes([5, 6, 7, 8])\n\
                   r = 0\nk = 0\n\
                   while k < 20:\n    r = total(key, 100)\n    k = k + 1\n\
                   def over(data):\n    i = 0\n    t = 0\n\
                   \x20   while i < 10:\n        t = t + data[i]\n        i = i + 1\n\
                   \x20   return t\n\
                   k = 0\nwhile k < 20:\n    over(key + key + key)\n    k = k + 1\n\
                   msg = ''\n\
                   try:\n    over(key)\nexcept IndexError:\n    msg = 'IndexError'\n\
                   print(r, msg)\n";
        let (out, compiled, _deopts) = run_jit(src);
        assert!(compiled >= 1, "bytes kernel never compiled");
        // 25 full key cycles (26 per) + data[-1] = 650 + 8.
        assert_eq!(out, "658 IndexError\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_str_attr_eq_through_instance() {
        // RFC 0071 WS6 + WS3 composed — `p.name == q.name`: the attr
        // sites fingerprint a `Str` lane and the comparison runs
        // native on the pinned values.
        let src = "class Named:\n    def __init__(self, name):\n        self.name = name\n\
                   def count(p, q, n):\n    t = 0\n    i = 0\n\
                   \x20   while i < n:\n\
                   \x20       if p.name == q.name:\n            t = t + 1\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   a = Named('al' + 'pha')\nb = Named('alp' + 'ha')\nc = Named('beta')\n\
                   r = 0\nk = 0\n\
                   while k < 20:\n    r = count(a, b, 100)\n    k = k + 1\n\
                   print(r, count(a, c, 100))\n";
        let (out, compiled, _deopts) = run_jit(src);
        assert!(compiled >= 1, "attr str-eq kernel never compiled");
        assert_eq!(out, "100 0\n");
        assert_eq!(out, run(src));
    }

    // RFC 0067 WS1/WS2 — native-to-native calls and the eval-breaker
    // poll.

    /// Like [`run_jit`], but returns the native-call fast-path
    /// counters instead: `(stdout, native_calls, fallbacks,
    /// native_deopts)`.
    #[cfg(feature = "jit")]
    fn run_jit_native(src: &str) -> (String, u64, u64, u64) {
        let src = src.to_owned();
        std::thread::spawn(move || {
            crate::tier2::force_enable_for_test(2);
            let out = run(&src);
            let (calls, fallbacks, deopts) = crate::tier2::native_call_stats_for_test();
            (out, calls, fallbacks, deopts)
        })
        .join()
        .expect("jit worker thread")
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_self_recursive_fib() {
        // The RFC 0067 poster child: once `fib` is compiled, its
        // recursive calls stay native — no interpreter frame, no
        // re-binding, no guard re-resolution per call.
        let src = "def fib(n):\n    if n < 2:\n        return n\n\
                   \x20   return fib(n - 1) + fib(n - 2)\n\
                   r = 0\nk = 0\n\
                   while k < 10:\n    r = fib(12)\n    k = k + 1\n\
                   print(r)\n";
        let (out, calls, _fallbacks, deopts) = run_jit_native(src);
        assert!(
            calls >= 1,
            "self-recursive fib never took the native call path"
        );
        assert_eq!(deopts, 0, "clean fib should not deopt a native callee");
        assert_eq!(out, "144\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_call_defaults_splice() {
        // RFC 0073 WS5 — an under-arity call site splices the trailing
        // defaults natively: both shapes of `add` below must take the
        // native-to-native path (no interpreter fallback per call).
        let src = "def add(a, b, c=7):\n\
                   \x20   return a * 100 + b * 10 + c\n\
                   def driver(n):\n\
                   \x20   t = 0\n\
                   \x20   i = 0\n\
                   \x20   while i < n:\n\
                   \x20       t = t + add(i, 2) + add(i, 2, 3)\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 60:\n    r = driver(40)\n    k = k + 1\n\
                   print(r)\n";
        let (out, calls, fallbacks, deopts) = run_jit_native(src);
        assert!(calls >= 1, "defaults-window calls never went native");
        assert_eq!(deopts, 0, "clean defaults splice should not deopt");
        assert_eq!(
            fallbacks, 0,
            "the under-arity site fell back to the interpreter call path"
        );
        assert_eq!(out, "158000\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_call_defaults_rebind_honored() {
        // RFC 0073 WS5 — `f.__defaults__ = …` lands in the slot store;
        // the native splice must refuse (the compiled tuple no longer
        // governs) and the interpreter's generic binder honours the
        // override. Function identity is unchanged, so the caller
        // stays compiled throughout.
        let src = "def f(a, b=1):\n    return a * 10 + b\n\
                   def driver(n):\n\
                   \x20   t = 0\n\
                   \x20   i = 0\n\
                   \x20   while i < n:\n        t = t + f(3)\n        i = i + 1\n\
                   \x20   return t\n\
                   t = 0\nk = 0\n\
                   while k < 50:\n    t = t + driver(20)\n    k = k + 1\n\
                   f.__defaults__ = (5,)\n\
                   j = 0\n\
                   while j < 50:\n    t = t + driver(20)\n    j = j + 1\n\
                   print(t)\n";
        let (out, _calls, _fallbacks, _deopts) = run_jit_native(src);
        // 50*20*31 + 50*20*35
        assert_eq!(out, "66000\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_call_kwnames() {
        // RFC 0073 WS5 — keyword call sites: the analyzer burns the
        // name → slot permutation, so both the in-order and the
        // shuffled keyword shapes marshal as plain positional prefixes
        // and take the native-to-native path.
        let src = "def add(a, b, c):\n\
                   \x20   return a * 100 + b * 10 + c\n\
                   def driver(n):\n\
                   \x20   t = 0\n\
                   \x20   i = 0\n\
                   \x20   while i < n:\n\
                   \x20       t = t + add(i, b=2, c=3) + add(i, c=5, b=4)\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 60:\n    r = driver(40)\n    k = k + 1\n\
                   print(r)\n";
        let (out, calls, fallbacks, deopts) = run_jit_native(src);
        assert!(calls >= 1, "keyword calls never went native");
        assert_eq!(deopts, 0, "clean keyword calls should not deopt");
        assert_eq!(
            fallbacks, 0,
            "a keyword site fell back to the interpreter call path"
        );
        // sum_{i<40} (100i + 23) + (100i + 45) = 2*100*780 + 40*68
        assert_eq!(out, "158720\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_call_kwnames_defaults_window() {
        // RFC 0073 WS5 — a keyword call that fills a *prefix* of the
        // parameters, with the tail bound from trailing defaults: the
        // filled set is contiguous, so the site composes with the
        // defaults splice.
        let src = "def add(a, b, c=7):\n\
                   \x20   return a * 100 + b * 10 + c\n\
                   def driver(n):\n\
                   \x20   t = 0\n\
                   \x20   i = 0\n\
                   \x20   while i < n:\n\
                   \x20       t = t + add(i, b=2)\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 60:\n    r = driver(40)\n    k = k + 1\n\
                   print(r)\n";
        let (out, calls, fallbacks, deopts) = run_jit_native(src);
        assert!(
            calls >= 1,
            "keyword defaults-window calls never went native"
        );
        assert_eq!(deopts, 0, "clean keyword defaults window should not deopt");
        assert_eq!(
            fallbacks, 0,
            "the keyword site fell back to the interpreter"
        );
        // sum_{i<40} 100i + 27 = 78000 + 1080
        assert_eq!(out, "79080\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_call_kwnames_gap_stays_interpreted() {
        // RFC 0073 WS5 — a keyword that *skips* a defaulted parameter
        // (`a`, then `c`, leaving the `b` gap to its default) is not a
        // contiguous fill: the frame stays interpreted and the output
        // is exact either way.
        let src = "def add(a, b=2, c=7):\n\
                   \x20   return a * 100 + b * 10 + c\n\
                   def driver(n):\n\
                   \x20   t = 0\n\
                   \x20   i = 0\n\
                   \x20   while i < n:\n\
                   \x20       t = t + add(i, c=9)\n\
                   \x20       i = i + 1\n\
                   \x20   return t\n\
                   r = 0\nk = 0\n\
                   while k < 60:\n    r = driver(40)\n    k = k + 1\n\
                   print(r)\n";
        let (out, _calls, _fallbacks, _deopts) = run_jit_native(src);
        // sum_{i<40} 100i + 29 = 78000 + 1160
        assert_eq!(out, "79160\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_cross_function_call() {
        // `outer`'s native loop calls a *different* compiled function
        // through the generation-cached native table. (The `< 0`
        // checks give the analyzer int evidence for the parameters —
        // the tier-2 subset types locals from use, not from probes.)
        let src = "def add(a, b):\n    if a < 0:\n        return 0\n\
                   \x20   if b < 0:\n        return 0\n\
                   \x20   return a + b\n\
                   def outer(n):\n    t = 0\n    i = 0\n\
                   \x20   while i < n:\n        t = add(t, i)\n        i = i + 1\n\
                   \x20   return t\n\
                   k = 0\nwhile k < 10:\n    add(1, 2)\n    k = k + 1\n\
                   r = 0\nk = 0\n\
                   while k < 10:\n    r = outer(100)\n    k = k + 1\n\
                   print(r)\n";
        let (out, calls, _fallbacks, deopts) = run_jit_native(src);
        assert!(calls >= 1, "cross-function call never went native");
        assert_eq!(deopts, 0, "clean add callee should not deopt");
        assert_eq!(out, "4950\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_callee_deopt_materializes_exactly() {
        // The nested callee overflows i64 mid-multiplication: its
        // native activation deopts, is materialized into a real frame,
        // and the interpreter finishes with the exact bigint.
        let src = "def mul(a, b):\n    if a < 0:\n        return 0\n\
                   \x20   if b < 0:\n        return 0\n\
                   \x20   return a * b\n\
                   k = 0\nwhile k < 10:\n    mul(2, 3)\n    k = k + 1\n\
                   def spin(n):\n    t = 1\n    i = 0\n\
                   \x20   while i < n:\n        t = mul(t, 3)\n        i = i + 1\n\
                   \x20   return t\n\
                   print(spin(50))\n";
        let (out, calls, _fallbacks, deopts) = run_jit_native(src);
        assert!(calls >= 1, "mul never took the native call path");
        assert!(deopts >= 1, "the i64 overflow must deopt the native callee");
        assert_eq!(out, run(src), "bigint overflow diverged from interpreter");
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_callee_raise_propagates() {
        // The nested native callee divides by zero on the last
        // iteration: the materialized frame raises, the exception
        // unwinds through the native caller, and the module-level
        // handler catches the real ZeroDivisionError.
        let src = "def div(a, b):\n    if a < 0:\n        return 0\n\
                   \x20   if b < 0:\n        return 0\n\
                   \x20   return a // b\n\
                   k = 0\nwhile k < 10:\n    div(9, 3)\n    k = k + 1\n\
                   def spin(n):\n    t = 0\n    i = 0\n\
                   \x20   while i < n:\n        t = t + div(10, n - i - 1)\n        i = i + 1\n\
                   \x20   return t\n\
                   try:\n    spin(5)\nexcept ZeroDivisionError:\n    print('zde ok')\n\
                   print(div(10, 2))\n";
        let (out, calls, _fallbacks, _deopts) = run_jit_native(src);
        assert!(calls >= 1, "div never took the native call path");
        assert_eq!(out, "zde ok\n5\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_recursion_limit_matches_interpreter() {
        // The native fast path charges the same recursion tick as the
        // interpreter, and on overflow routes through the interpreter
        // so RecursionError fires at the same depth with full fidelity.
        let src = "import sys\nsys.setrecursionlimit(100)\n\
                   def down(n):\n    if n == 0:\n        return 0\n\
                   \x20   return down(n - 1)\n\
                   k = 0\nwhile k < 10:\n    down(5)\n    k = k + 1\n\
                   try:\n    down(100000)\nexcept RecursionError:\n    print('rec ok')\n";
        let (out, calls, _fallbacks, _deopts) = run_jit_native(src);
        assert!(calls >= 1, "down never took the native call path");
        assert_eq!(out, "rec ok\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_native_lane_mismatch_falls_back() {
        // `dbl` compiled for int arguments; the native caller passes a
        // float — the argument-lane check rejects the fast path and
        // the interpreter call stays exact.
        let src = "def dbl(x):\n    if x < 0:\n        return 0\n\
                   \x20   return x + x\n\
                   k = 0\nwhile k < 10:\n    dbl(3)\n    k = k + 1\n\
                   def spin(n):\n    t = 0.0\n    i = 0\n\
                   \x20   while i < n:\n        t = t + dbl(0.5)\n        i = i + 1\n\
                   \x20   return t\n\
                   r = 0.0\nk = 0\n\
                   while k < 10:\n    r = spin(20)\n    k = k + 1\n\
                   print(r)\n";
        let (out, _calls, fallbacks, _deopts) = run_jit_native(src);
        assert!(fallbacks >= 1, "float-for-int argument must fall back");
        assert_eq!(out, "20.0\n");
        assert_eq!(out, run(src));
    }

    #[cfg(feature = "jit")]
    #[test]
    fn jit_poll_observes_cross_thread_flag() {
        // RFC 0067 WS2 — the spin-on-a-flag idiom. `done` burns into
        // the native loop as a constant `False`; the worker thread can
        // only run at all because the loop's poll hands off the GIL,
        // and the rebind is observed because the poll revalidates the
        // activation's guards (bounding staleness to one stride). If
        // either half regresses, the loop runs to its 2e9 bound and
        // prints False instead of hanging the suite.
        let src = "import threading\nimport time\n\
                   done = False\n\
                   def worker():\n    global done\n    time.sleep(0.2)\n    done = True\n\
                   t = threading.Thread(target=worker)\nt.start()\n\
                   def spin(limit):\n    i = 0\n\
                   \x20   while i < limit:\n        if done:\n            break\n        i = i + 1\n\
                   \x20   return i\n\
                   r = spin(2000000000)\nt.join()\n\
                   print(r < 2000000000)\n";
        let (out, _compiled, _deopts) = run_jit(src);
        assert_eq!(out, "True\n", "native loop failed to observe the flag");
    }

